import{_ as a,a0 as e,w as i,s as p,ao as s,I as l,x as n,a1 as r,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const I=JSON.parse('{"title":"Ubuntu After Install – 幫你在Ubuntu上自動安裝流行的軟件 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu After Install – 幫你在Ubuntu上自動安裝流行的軟件 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu After Install – 幫你在Ubuntu上自動安裝流行的軟件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu After Install – 幫你在Ubuntu上自動安裝流行的軟件 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/Ubuntu After Install--Automate the Installation of all popular softwares On Ubuntu 14.04 or 13.10 or 13.04 or 12.10 or 12.04","title":"Ubuntu After Install – 幫你在Ubuntu上自動安裝流行的軟件","tag":"201405","desc":""},"relativePath":"201405/Ubuntu After Install--Automate the Installation of all popular softwares On Ubuntu 14.04 or 13.10 or 13.04 or 12.10 or 12.04.md","filePath":"[post].md"}'),b={name:"201405/Ubuntu After Install--Automate the Installation of all popular softwares On Ubuntu 14.04 or 13.10 or 13.04 or 12.10 or 12.04.md"};function g(f,t,d,U,m,A){const u=e("Link");return i(),p("div",null,[t[22]||(t[22]=s(`<h1 id="ubuntu-after-install-–-幫你在ubuntu上自動安裝流行的軟件" tabindex="-1">Ubuntu After Install – 幫你在Ubuntu上自動安裝流行的軟件 <a class="header-anchor" href="#ubuntu-after-install-–-幫你在ubuntu上自動安裝流行的軟件" aria-label="Permalink to “Ubuntu After Install – 幫你在Ubuntu上自動安裝流行的軟件”">​</a></h1><p>在你剛剛更新或者是安裝了一個新的Ubuntu桌面版之後，你是不是想安裝一些有用的並且必要的軟件呢？當然。但是，為了打造一個完美的Ubuntu系統，你會需要付出很大的努力。你還會嗎？你會怎麼去做？你真的會去手動通過添加軟件源或者是下載<strong>.deb</strong>包去尋找和安裝每一個軟件？或者不分青紅皂白安裝所有的軟件？我覺得這將是一個漫長的過程，並且你們也不知道你們需要什麼軟件去打造這麼一個完美的Ubuntu桌面。</p><p>好的，如果有一個簡單的工具能讓你達到上面的目的，且只需要你點擊兩下鼠標，你會怎麼做？這真會有一個簡單的並且有趣的工具，幫助我們安裝所有的必須和流行的軟件，並且只需要雙擊鼠標？是的，還真有。為了滿足你的好奇心，我可以很負責任的告訴你，這就是<strong>Ubuntu After Install</strong>。</p><p><strong>Ubuntu After Install</strong>是用來在安裝Ubuntu桌面之後安裝一些最好的和必要的軟件的工具。還有，它還包含了許多有用的應用程序，並且可以自動執行安裝過程新安裝的機器，讓它接近完美的桌面。我不敢説它可以提供給所有用户一個完美的桌面，但一個近乎完美的桌面絕對是可以的。這個工具不僅可以節省您的時間和精力，而且會自動添加相應的PPA來自動更新，讓你始終使用着最新的軟件。</p><p><strong>Ubuntu After Install</strong>會安裝的軟件的完整名單如下：</p><ul><li><strong>Ubuntu Restricted Extras</strong>: 視頻解碼和Flash支持</li><li><strong>libdvdcss</strong> DVD重放</li><li><strong>Unity Tweak Tool</strong> 優化你的Ubuntu桌面</li><li><strong>Variety</strong> Ubuntu桌面壁紙切換</li><li><strong>Google Chrome</strong> 可能是世界上最好的瀏覽器</li><li><strong>LibreOffice</strong> 完全開源的辦公軟件</li><li><strong>Skype</strong> 提供文字，聲音，視頻聊天</li><li><strong>Grive Tools</strong> 同步你的Google Driver</li><li><strong>DropBox</strong> 同步你的DropBox存儲</li><li><strong>VLC</strong> 能播放你能想像的視頻文件</li><li><strong>XBMC</strong> 一個媒體中心軟件</li><li><strong>Radio Tray</strong> 一款不錯的基於面板的廣播系統</li><li><strong>GIMP</strong> 強大的圖片編輯軟件</li><li><strong>Darktable</strong> 允許攝影師編輯RAW文件</li><li><strong>Inkscape</strong> 開源矢量圖形編輯軟件</li><li><strong>Scribus</strong> 專業的桌面發佈軟件</li><li><strong>Samba</strong> 允許Windows網絡共享</li><li><strong>PDF Tools</strong> 合併、剪切、添加、修改PDF文檔工具</li><li><strong>OpenShot</strong> 流行的視頻編輯軟件</li><li><strong>Kdenlive</strong> 更加先進的視頻編輯軟件</li><li><strong>Handbrake</strong> 將視頻和DVD轉換為移動端可播放格式</li><li><strong>Audacity</strong> 聲音，音樂編輯工具</li><li><strong>Steam</strong> Linuxu遊戲平台</li><li><strong>KeePass</strong> 安全的儲存你的密碼</li><li><strong>Shutter</strong> 讓你很容易的截屏</li><li><strong>FileZilla</strong> FTP工具</li><li><strong>p7zip</strong> 強大的7zip壓縮/解壓工具</li><li>還有一些即將到來的新特性</li></ul><h3 id="在ubuntu-12-04或者更新一些的系統上-安裝-ubuntu-after-install" tabindex="-1">在Ubuntu 12.04或者更新一些的系統上 安裝‘Ubuntu After Install’ <a class="header-anchor" href="#在ubuntu-12-04或者更新一些的系統上-安裝-ubuntu-after-install" aria-label="Permalink to “在Ubuntu 12.04或者更新一些的系統上 安裝‘Ubuntu After Install’”">​</a></h3><p>添加‘Ubuntu After Install’ PPA 並且執行以下命令</p><pre><code>sudo add-apt-repository ppa:thefanclub/ubuntu-after-install
sudo apt-get update
sudo apt-get install ubuntu-after-install
</code></pre>`,9)),l("p",null,[t[1]||(t[1]=n("你也可以從",-1)),r(u,{href:"http://www.thefanclub.co.za/sites/all/modules/pubdlcnt/pubdlcnt.php?file=http://www.thefanclub.co.za/sites/default/files/public/downloads/ubuntu-after-install_2.4_all.deb&nid=121"},{default:o(()=>[...t[0]||(t[0]=[n("這裏",-1)])]),_:1}),t[2]||(t[2]=n("手動下載 .deb 文件，並且手動安裝。",-1))]),t[23]||(t[23]=s('<h3 id="使用説明" tabindex="-1">使用説明 <a class="header-anchor" href="#使用説明" aria-label="Permalink to “使用説明”">​</a></h3><p>安裝完Ubuntu-After-Install之後，你只需要從Dash或者菜單裏啓動他即可。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/04/Menu_001.png" alt=""></p><p>這就是Ubuntu-after-install的外觀。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/04/Ubuntu-After-Install-2.4-beta_002.png" alt=""></p><p>正如你在上面的截圖中看到，它會顯示所有有用的軟件。已經被安裝了軟件會標有綠色的色點，且默認不會選中。如果某一款軟件不適用於您的Ubuntu版本，那麼它將被標記為紅色圓點。還有，標誌着橙色的軟件則是需要重新安裝和更新的。清楚了嗎？</p><p>現在，選擇您想要安裝並按下按鈕<strong>立即安裝</strong>。所選軟件的PPA將會自動添加到系統中，並且也會在系統上自動安裝。聽起來不錯，不是嗎？</p><p>例如，在這裏我只想安裝在我的Ubuntu14.04系統上安裝p7zip。所以我只選擇了p7zip的包，並取消其他的程序。只需要輕輕點擊<strong>立即安裝</strong>按鈕，就可以開始安裝。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/04/Ubuntu-After-Install-2.4-beta_003.png" alt=""></p><p>現在，安裝程序會在你電腦上自動添加p7zip的PPA並且安裝它。而且一切都將自動在後台完成。所以，你什麼都不需要做。只需要，要放鬆心情，喝杯咖啡，觀看安裝。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/04/Ubuntu-After-Install-2.4-beta_004.png" alt=""></p><p>如果軟件已經安裝成功，它將被標記為綠色的色點。請記住，一次安裝所有的應用程序將需要一段時間取決於您的Internet連接速度來完成的，這是安裝過程一旦開始，強行取消是非常不可取的。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3>',13)),l("p",null,[t[4]||(t[4]=n("在之前，我們剛剛提到了",-1)),r(u,{href:"http://www.unixmen.com/after-a-fresh-install-of-ubuntu-1010-maverick-meerkat-configuration-made-easy-with-ubuntu-tweak/"},{default:o(()=>[...t[3]||(t[3]=[n("Ubuntu Tweak",-1)])]),_:1}),t[5]||(t[5]=n("。 ",-1)),t[6]||(t[6]=l("strong",null,"Ubuntu Tweak",-1)),t[7]||(t[7]=n("和",-1)),t[8]||(t[8]=l("strong",null,"Ubuntu After Install",-1)),t[9]||(t[9]=n("是類似的工具, 但是Ubuntu Tweak有着比Ubuntu After Install更多的特點。 Ubuntu After Tool只是為了幫你安裝了所有最好的和日常使用的軟件, 而Ubuntu的調整工具會做對額外的東西，如定製您的Ubuntu桌面和更多。",-1))]),t[24]||(t[24]=l("p",null,"不要再在網絡上尋找所謂的Ubuntu必備軟件上浪費你的寶貴的時間。Ubuntu Tweak和Ubuntu After Install就是為了幫助那些正在尋找Ubuntu必備軟件的人準備的。所以，不要再猶豫，馬上使用它們！",-1)),t[25]||(t[25]=l("p",null,"希望能幫助到你，就説這麼多了。",-1)),t[26]||(t[26]=l("p",null,"祝你好運!",-1)),t[27]||(t[27]=l("p",null,"來源與參考:",-1)),l("ul",null,[l("li",null,[r(u,{href:"http://www.thefanclub.co.za/how-to/ubuntu-after-install"},{default:o(()=>[...t[10]||(t[10]=[n("The Fan Club Website",-1)])]),_:1})])]),t[28]||(t[28]=l("hr",null,null,-1)),l("p",null,[t[12]||(t[12]=n("via: ",-1)),r(u,{href:"http://www.unixmen.com/ubuntu-install-automate-installation-popular-softwares-ubuntu-14-0413-1013-0412-1012-04/"},{default:o(()=>[...t[11]||(t[11]=[n("http://www.unixmen.com/ubuntu-install-automate-installation-popular-softwares-ubuntu-14-0413-1013-0412-1012-04/",-1)])]),_:1})]),l("p",null,[t[15]||(t[15]=n("譯者：",-1)),r(u,{href:"https://github.com/MikeCoder"},{default:o(()=>[...t[13]||(t[13]=[n("MikeCoder",-1)])]),_:1}),t[16]||(t[16]=n(" 校對：",-1)),r(u,{href:"https://github.com/%E6%A0%A1%E5%B0%8D%E8%80%85ID"},{default:o(()=>[...t[14]||(t[14]=[n("校對者ID",-1)])]),_:1})]),l("p",null,[t[19]||(t[19]=n("本文由 ",-1)),r(u,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[17]||(t[17]=[n("LCTT",-1)])]),_:1}),t[20]||(t[20]=n(" 原創翻譯，",-1)),r(u,{href:"http://linux.cn/"},{default:o(()=>[...t[18]||(t[18]=[n("Linux中國",-1)])]),_:1}),t[21]||(t[21]=n(" 榮譽推出",-1))])])}const C=a(b,[["render",g]]);export{I as __pageData,C as default};
